options.onCreated:
const _this = this
async function getList() {
  try {
    const data = await $api.get('/docpal/case/types?deployed=true').then(res => res.data.data)
    return data.reduce((prev, item) => {
      if(!item.id ) return prev 
      const resultItem = {
        value: item.id,
        label: item.name,
        tableName: item.tableName,
        uniqueName: item.uniqueName
      }
      prev.push(resultItem) 
      return prev
    }, []).sort((a,b)=> (a.label.localeCompare(b.label) ))
  } catch (e) { return [] }
}
async function init() {
  const options = await getList()
  _this.loadOptions(options)
}
init()

options.onChange:
const _this = this
if(!value) return
async function getList() {
  try {
    const data = await $api.get(`/docpal/case/types/${value}/caseInfo`).then(res => res.data.data)
    return data.reduce((prev, item) => {
      if(!item.id || !item.name) return prev 
      const resultItem = {
        value: item.id,
        label: item.name || '' ,
        type: item.type
      }
      prev.push(resultItem) 
      return prev
    }, []).sort((a,b)=> (a.label.localeCompare(b.label) ))
  } catch (e) { return [] }
}
async function init() {
  const options = await getList()
  const relatedFieldRef = _this.getWidgetRef('relatedField')
  relatedFieldRef.loadOptions(options)
  const filterKeyRef = _this.getWidgetRef('filterKey')
  filterKeyRef.loadOptions(options)
  const strOptions = options.filter(i => ['string','short_text'].includes(i.type))
  const currentUserFieldRef = _this.getWidgetRef('currentUserField')
  currentUserFieldRef.loadOptions(strOptions)
  const sortByRef = _this.getWidgetRef('sortBy')
  sortByRef.loadOptions(options)
  const dateOptions = options.filter(i => ['date'].includes(i.type))
  const dateFieldRef = _this.getWidgetRef('dateField')
  dateFieldRef.loadOptions(dateOptions)
  const displayColumnsRef = _this.getWidgetRef('displayColumns')
  displayColumnsRef.loadOptions(options)
  const displayColumnsValue = displayColumnsRef.getValue()
  if(!displayColumnsValue || displayColumnsValue.length === 0) displayColumnsRef.setValue(['case_id'])
  const fields = _this.getWidgetRef('fields')
  fields.setValue(JSON.stringify(options))

  initNumberOptions(options)
}
function initNumberOptions(options) {
  const averageFieldRef = _this.getWidgetRef('averageField')
  const numberOptions = options.filter(item => ['float'].includes(item.type))
  averageFieldRef.loadOptions(numberOptions)
}
function initDialogTitle() {
  const optionItems = _this.getOptionItems()
  const dialogSettingTitleRef = _this.getWidgetRef('dialogSettingTitle')
  const title = dialogSettingTitleRef.getValue()
  const cur = optionItems.find(i => i.value === value)
  const isTitle = !title || optionItems.find(i => i.label === title)
  if(cur && isTitle) dialogSettingTitleRef.setValue(cur.label)
}
function initTableName() {
  if(!value) return
  const optionItems = _this.getOptionItems()
  const cur = optionItems.find(i => i.value === value)
  if(!cur) return
  const tableNameRef = _this.getWidgetRef('tableName')
  tableNameRef.setValue(cur.tableName)
}
initTableName()
initDialogTitle()
init()

// averageTitle
const _this = this
function initDialogTitle() {
  const optionItems = _this.getOptionItems()
  const titleRef = _this.getWidgetRef('averageTitle')
  const title = titleRef.getValue()
  const cur = optionItems.find(i => i.value === value)
  const isTitle = !title || optionItems.find(i => i.label === title)
  if(cur && isTitle) titleRef.setValue(cur.label)
  initTitle(optionItems)
}
function initTitle (options) {
  const titleRef = _this.getWidgetRef('title')
  const title = titleRef.getValue()
  const cur = options.find(i => i.value === value)
  const isTitle = !title || options.find(i => getTitle(i.label) === title) || title === 'Number of Cases'
  if(cur && isTitle) titleRef.setValue(getTitle(cur.label))
}
function getTitle(lable) {
  return `Number of Cases & Average ${lable} by Month`
}
initDialogTitle()

const _this = this
const filterKey = 'masterTableColumn'
async function getList() {
  try {
    const data = await $api.post('/docpal/master/tables/record/page/nonPermission',{where:{key: 'case_status', }, name: 'basic', }).then(res => res.data.data)
    return data.reduce((prev, item) => {
      if(!item.name || !item.name || prev.find(p => p.value === item.name)) return prev 
      const resultItem = {
        value: item.name,
        label: item.name || '' ,
        order_num: item.order_num
      }
      if(filterKey === 'user') resultItem.disabled = item.status === 'A' ? false : true 
      else if(filterKey === 'masterTableColumn') resultItem.disabled = !item.status
      prev.push(resultItem) 
      return prev
    }, []).sort((a,b)=> (a.order_num - b.order_num ))
  } catch (e) { return [] }
}
async function init() {
  const filterValueRef = _this.getWidgetRef('filterValue')
  if(value.includes('Case_Status')) {
    const options = await getList()
    filterValueRef.loadOptions(options)
  } else {
    filterValueRef.loadOptions([])
  }
}

init()
